using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Windows.Forms;
namespace Stackshot
{
    static class PopupAndCaptureFeedbackTests
    {
        [DllImport("user32.dll")]static extern int GetWindowLong(IntPtr window,int index);
        static System.Collections.Generic.IEnumerable<Control> Children(Control parent){foreach(Control c in parent.Controls){yield return c;foreach(var child in Children(c))yield return child;}}
        static void Click(Button button){typeof(Button).GetMethod("OnClick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(button,new object[]{EventArgs.Empty});}
        static CaptureOverlay Overlay(Preferences preferences=null,Rectangle? range=null){var image=new Bitmap(1000,700);using(var g=Graphics.FromImage(image))g.Clear(Color.FromArgb(220,225,232));return new CaptureOverlay(image,new Rectangle(0,0,1000,700),range??new Rectangle(100,100,700,400),new[]{new Rectangle(0,0,1000,680)},null,70,preferences);}
        internal static void Closed(StyledMenu menu){typeof(ToolStripDropDown).GetMethod("OnClosed",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(menu,new object[]{new ToolStripDropDownClosedEventArgs(ToolStripDropDownCloseReason.ItemClicked)});}
        public static void Run(Action<string,Action> run,Action<bool,string> check,string output)
        {
            run("popup/selection close retains native menu until owning field is disposed",delegate{using(var owner=new Form())using(var choice=new PreferencesChoice("RGB","HEX","HSL")){owner.Controls.Add(choice);var menu=choice.PreparePopup();var handle=menu.Handle;for(int i=0;i<40;i++){((ToolStripMenuItem)menu.Items[i%3]).PerformClick();Closed(menu);check(!menu.IsDisposed,"StyledMenu disposed inside Closed callback before native click unwinds");check(choice.PreparePopup()==menu&&menu.Handle==handle,"popup recreated during close/reopen");}check(!owner.Visible&&!menu.Visible,"lifecycle test showed UI");choice.Dispose();check(menu.IsDisposed,"owning field leaked menu");}});
            run("popup/drawn ellipse recolors through palette and repeatedly closes without disposed menu",delegate{using(var overlay=Overlay()){var c=overlay.AnnotationCanvas;var ellipse=ScreenCraftTests.Mark(Tool.Ellipse,200,180,500,350);ellipse.FillEnabled=true;ellipse.FillColor=Color.FromArgb(180,255,48,83);c.AddAnnotation(ellipse);var menu=overlay.PrepareColorMenu();var handle=menu.Handle;var panel=(AnnotationPalette)((ToolStripControlHost)menu.Items[0]).Control;var colors=Children(panel).OfType<PaletteSwatch>().ToArray();Color before=Color.Empty;for(int i=0;i<40;i++){before=c.SelectedShape.Color;var button=colors[i%colors.Length];Click(button);Closed(menu);check(c.SelectedShape.Color.ToArgb()==button.Ink.ToArgb()&&c.SelectedShape.FillColor.ToArgb()==Color.FromArgb(180,button.Ink).ToArgb(),"palette changed wrong color role");check(!menu.IsDisposed&&overlay.PrepareColorMenu()==menu&&menu.Handle==handle,"palette lifetime/reopen broke");using(var image=c.Render())check(image.Width==700,"recolor lost capture");}c.Undo();check(c.AnnotationSnapshot.Single().Color==before,"recolor undo lost prior ink");overlay.Dispose();check(menu.IsDisposed,"capture owner leaked palette");}});
            run("popup/live note palette changes accent background and preserves white glyphs and input",delegate{using(var overlay=Overlay()){var c=overlay.AnnotationCanvas;var note=ScreenCraftTests.Mark(Tool.Counter,250,230,250,230);note.Text="说明";c.AddAnnotation(note);c.EditNote();var input=c.Controls.OfType<TextBox>().Single();input.Text="建筑分析说明";var menu=overlay.PrepareColorMenu();var panel=(AnnotationPalette)((ToolStripControlHost)menu.Items[0]).Control;var color=Children(panel).OfType<PaletteSwatch>().ElementAt(6);Click(color);Closed(menu);check(c.Typing&&input.Text=="建筑分析说明"&&input.ForeColor.ToArgb()==Color.White.ToArgb()&&input.BackColor.ToArgb()==color.Ink.ToArgb()&&c.SelectedShape.Color==color.Ink,"note color changed anchor or text");c.CommitText();check(c.SelectedShape.Text=="建筑分析说明","note commit lost text");}});
            run("palette/two screenshot-derived preset sets have seven distinct colors each",delegate{using(var palette=new AnnotationPalette(Color.Red,delegate{},delegate{})){var colors=Children(palette).OfType<PaletteSwatch>().ToArray();check(colors.Length==14&&colors.Select(c=>c.Ink.ToArgb()).Distinct().Count()==14,"missing or duplicate palette colors");check(colors.Count(c=>(string)c.Tag=="常用")==7&&colors.Count(c=>(string)c.Tag=="分析图")==7,"two groups lost");check(colors.Any(c=>c.AccessibleName=="常用 · 红色 #FB3838")&&colors.Any(c=>c.AccessibleName=="分析图 · 青绿 #85C4C2"),"reference colors missing");using(var image=palette.RenderOffscreen())image.Save(Path.Combine(output,"annotation-palette-offscreen.png"));}});
            run("palette/hosted grid fits menu without native image gutter or phantom command rows",delegate{using(var overlay=Overlay()){var menu=overlay.PrepareColorMenu();var host=(ToolStripControlHost)menu.Items[0];check(menu.Items.Count==1&&!menu.ShowImageMargin&&menu.ClientRectangle.Contains(host.Bounds),"palette host clipped or native rows remain");check(host.Control.Width>=(int)(304*overlay.AnnotationCanvas.Ui)&&host.Width>=host.Control.Width,"palette grid width ignored");using(var image=menu.RenderOffscreen())image.Save(Path.Combine(output,"annotation-palette-menu-native.png"));check(!overlay.Visible&&!menu.Visible,"palette shown");}});
            run("toolbar/properties remain immediately below tools at all corners and both placement preferences",delegate{foreach(string placement in new[]{"top","bottom"})foreach(var range in new[]{new Rectangle(0,0,400,180),new Rectangle(600,500,400,180),new Rectangle(0,500,400,180),new Rectangle(600,0,400,180),new Rectangle(100,130,780,450)})using(var overlay=Overlay(new Preferences{ToolbarPlacement=placement},range)){foreach(var kind in new[]{Tool.Rect,Tool.Ellipse,Tool.Text,Tool.Counter}){overlay.AnnotationCanvas.SetTool(kind);check(overlay.OptionsBounds.Top==overlay.ToolbarBounds.Bottom+(int)Math.Round(6*overlay.AnnotationCanvas.Ui)&&overlay.OptionsBounds.Left==overlay.ToolbarBounds.Left,"properties separated from tools");check(new Rectangle(0,0,1000,680).Contains(overlay.ToolbarBounds)&&new Rectangle(0,0,1000,680).Contains(overlay.OptionsBounds),"combined toolbar outside monitor");}if(placement=="bottom"&&range.Top==130)using(var image=overlay.RenderSyntheticPreview())image.Save(Path.Combine(output,"toolbar-block-above-offscreen.png"));}});
            run("settings/capture controls edit mask frame color width placement and startup notice and restore defaults",delegate{Preferences saved=null;using(var dialog=new SettingsDialog(new Preferences(),"fixture",delegate(Preferences p){saved=p;return "fixture keeps hidden";})){var controls=Children(dialog).ToArray();controls.OfType<NumericUpDown>().Single(n=>n.AccessibleName=="压暗百分比").Value=81;controls.OfType<PreferencesChoice>().Single(n=>n.AccessibleName=="选区边框粗细").SelectedIndex=2;controls.OfType<PreferencesChoice>().Single(n=>n.AccessibleName=="选区边框颜色").SelectedIndex=1;controls.OfType<PreferencesChoice>().Single(n=>n.AccessibleName=="编辑工具条位置").SelectedIndex=1;controls.OfType<PreferencesSwitch>().Single(n=>n.AccessibleName=="启动时显示悬浮提示").Checked=false;Click(controls.OfType<Button>().Single(b=>b.Text=="保存并应用"));check(saved.SelectionDimPercent==81&&saved.SelectionBorderWidth==6&&saved.SelectionBorderColor=="green"&&saved.ToolbarPlacement=="top"&&!saved.ShowStartupNotice,"capture settings were display-only or lost on save");foreach(var label in controls.OfType<Label>().Where(l=>l.Text=="fixture keeps hidden"))label.Text="";using(var image=dialog.RenderSyntheticPreview(1))image.Save(Path.Combine(output,"settings-capture-editable-offscreen.png"));dialog.ClientSize=new Size(720,520);foreach(var label in controls.OfType<Label>().Where(l=>l.Text=="fixture keeps hidden"))label.Text="";using(var image=dialog.RenderSyntheticPreview(1))image.Save(Path.Combine(output,"settings-capture-compact-offscreen.png"));Click(controls.OfType<Button>().Single(b=>b.Text=="恢复默认"));Click(controls.OfType<Button>().Single(b=>b.Text=="保存并应用"));check(saved.SelectionDimPercent==70&&saved.SelectionBorderWidth==4&&saved.SelectionBorderColor=="blue"&&saved.ToolbarPlacement=="bottom"&&saved.ShowStartupNotice,"defaults incomplete");check(!dialog.Visible,"settings shown");}});
            run("preferences/capture appearance and notice migrate missing fields and persist explicit values",delegate{var store=new PreferenceStore(Path.Combine(output,"capture-feedback-settings"));Directory.CreateDirectory(store.DirectoryPath);File.WriteAllText(store.FilePath,"{\"Version\":1}");var defaults=store.Load();check(defaults.SelectionBorderWidth==4&&defaults.SelectionBorderColor=="blue"&&defaults.ToolbarPlacement=="bottom"&&defaults.ShowStartupNotice,"legacy migration defaults");defaults.SelectionBorderWidth=6;defaults.SelectionBorderColor="orange";defaults.ToolbarPlacement="top";defaults.ShowStartupNotice=false;store.Save(defaults);var read=store.Load();check(read.SelectionBorderWidth==6&&read.SelectionBorderColor=="orange"&&read.ToolbarPlacement=="top"&&!read.ShowStartupNotice,"preferences roundtrip");});
            run("selection/stronger frame remains distinct on light dark and screenshot edges",delegate{foreach(var bg in new[]{Color.White,Color.Black,Color.FromArgb(128,128,128)})foreach(int width in new[]{2,4,6})using(var image=new Bitmap(180,150))using(var g=Graphics.FromImage(image)){g.Clear(bg);var color=SelectionAppearance.BorderColor("green");SelectionAppearance.PaintFrame(g,new Rectangle(30,30,120,90),width,color);check(image.GetPixel(80,29).G>150&&image.GetPixel(80,30).R>240,"contrast frame missing on background");SelectionAppearance.PaintFrame(g,new Rectangle(0,0,179,149),width,color);check(image.GetPixel(1,80).G>150&&image.GetPixel(178,80).G>150,"frame disappeared at desktop boundary");if(bg==Color.White&&width==4)image.Save(Path.Combine(output,"selection-strong-frame-offscreen.png"));}check(SelectionAppearance.BorderWidth(0)==2&&SelectionAppearance.BorderWidth(100)==6,"unsafe thickness");});
            run("startup/notice policy and nonactivating hidden toast stay above taskbar and expire",delegate{check(StartupPolicy.ShowsNotice(new string[0],new Preferences())&&StartupPolicy.ShowsNotice(new[]{"--background"},new Preferences())&&!StartupPolicy.ShowsNotice(new[]{"--settings"},new Preferences())&&!StartupPolicy.ShowsNotice(new string[0],new Preferences{ShowStartupNotice=false}),"startup routing or opt-out");var area=new Rectangle(-1920,0,1920,1040);using(var toast=new StartupToast(area,"Alt+A",false,1)){int style=GetWindowLong(toast.Handle,-20);check((style&0x08000000)!=0&&(style&0x80)!=0&&!toast.ShowInTaskbar&&!toast.Visible,"toast activates or uses taskbar");var final=StartupToast.Placement(area,toast.Size);check(toast.Advance(TimeSpan.Zero)&&toast.Top==final.Top+12&&toast.Bottom<area.Bottom,"initial toast placement");check(toast.Advance(TimeSpan.FromMilliseconds(180))&&toast.Bounds==final,"rise destination");check(!toast.Advance(TimeSpan.FromMilliseconds(2700))&&!toast.Visible,"toast did not expire");using(var image=toast.RenderOffscreen())image.Save(Path.Combine(output,"startup-toast-offscreen.png"));}});
            run("style/reference cards retain white fields square swatches offset shadow and active property heading",delegate{using(var swatch=new PaletteSwatch{Ink=Color.Red})using(var choice=new PreferencesChoice("RGB","HEX"))using(var circle=UiPaintingTests.NativePaint(swatch,Color.Magenta))using(var input=UiPaintingTests.NativePaint(choice,Color.Magenta)){check(circle.GetPixel(4,15).ToArgb()==Color.White.ToArgb()&&circle.GetPixel(15,7).R>240&&circle.GetPixel(7,15).R>240&&circle.GetPixel(15,15).R>240&&circle.GetPixel(15,15).G<10,"swatch is not a clean square color swatch");check(input.GetPixel(150,10).ToArgb()==Color.White.ToArgb(),"choice is not a white field");}using(var image=new Bitmap(160,90))using(var g=Graphics.FromImage(image)){g.Clear(PreferencesLook.Background);PreferencesLook.FloatingCard(g,new Rectangle(10,10,120,50),10);check(image.GetPixel(70,35).ToArgb()==Color.White.ToArgb()&&image.GetPixel(70,60).R<PreferencesLook.Background.R,"white card or offset soft shadow missing");}using(var overlay=Overlay()){overlay.AnnotationCanvas.SetTool(Tool.Arrow);check(Children(overlay).OfType<Label>().Single(l=>l.AccessibleName=="当前工具属性").Text=="箭头","property heading did not follow current tool");}});
        }
    }
}
